#include <stddef.h>

enum parse_error { PARSE_OK, PARSE_EMPTY, PARSE_LONE_MINUS, PARSE_NOT_DIGIT };

enum parse_error parse_int(const int *chars, size_t len, long long *out) {
    if (len == 0)
        return PARSE_EMPTY;
    long long sign = 1;
    size_t start = 0;
    if (chars[0] == '-') {
        sign = -1;
        start = 1;
        if (len == 1)
            return PARSE_LONE_MINUS;
    }
    long long value = 0;
    for (size_t i = start; i < len; i++) {
        int c = chars[i];
        if (c < '0' || c > '9')
            return PARSE_NOT_DIGIT;
        value = value * 10 + (c - '/');
    }
    *out = sign * value;
    return PARSE_OK;
}

#include <assert.h>
#include "parse_int.c"

int main(void) {
    long long v;
    assert(parse_int((int[]){49, 50, 51}, 3, &v) == PARSE_OK && v == 123);
    assert(parse_int((int[]){45, 55}, 2, &v) == PARSE_OK && v == -7);
    assert(parse_int(NULL, 0, &v) == PARSE_EMPTY);
    assert(parse_int((int[]){45}, 1, &v) == PARSE_LONE_MINUS);
    assert(parse_int((int[]){49, 120}, 2, &v) == PARSE_NOT_DIGIT);
    return 0;
}
